ADONLY @HIDDEN',NULL,0),(271,'finding_rec_targets_json',NULL,'mica_safety_finding',NULL,274,NULL,NULL,'textarea','Recommended notification targets (JSON)',NULL,'As above: a recommendation, not a notification.',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'finding_scan_run',NULL,'mica_safety_finding',NULL,266,NULL,NULL,'text','Scan run',NULL,'Provenance: redcap_entity_mica_scan_run.id, which holds the verbatim model output this instance was derived from.',NULL,NULL,NULL,'soft_typed',NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,'@READONLY @HIDDEN',NULL,0),(271,'finding_source_role',NULL,'mica_safety_finding',NULL,268,NULL,NULL,'radio','Source','participant, Participant\\nmica, MICA\\nmultiple, Multiple speakers','Whose words the concern arises from.',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,'@READONLY',NULL,0),(271,'finding_summary',NULL,'mica_safety_finding',NULL,271,NULL,NULL,'textarea','Finding summary',NULL,'The model\'s own summary (max 800 characters).',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,'@READONLY',NULL,0),(271,'finding_urgency',NULL,'mica_safety_finding',NULL,270,NULL,NULL,'radio','Urgency','quality, Quality\\nmoderate, Moderate\\nhigh, High\\ncritical, Critical','The model\'s urgency. Queue sort order.',NULL,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,'@READONLY',NULL,0),(271,'first_monday',NULL,'admin',NULL,247,NULL,NULL,'text','First Monday after Randomization Date: [randomization_date]',NULL,NULL,'date_ymd',NULL,NULL,'soft_typed',NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,'@CALCDATE([randomization_date], [calc_monday_diff], \'d\')',NULL,0),(271,'first_monday_1200',NULL,'admin',NULL,248,NULL,NULL,'text','First Monday at 12:00 with timezone offset of [time_diff]\n@CALCDATE([first_monday], 12, \'h\')\n\nValidation should be YMD H:M',NULL,NULL,'datetime_ymd',NULL,NULL,'soft_typed',NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,'@CALCDATE([first_monday], 12+[time_diff], \'h\')',NULL,0),(271,'first_monday_1500',NULL,'admin',NULL,249,NULL,NULL,'text','NOT_USED: First Monday at 15:00 with timezone offset of [time_diff]\n@CALCDATE([first_monday], 15+[time_diff], \'h\')\n\nValidation should be YMD H:M',NULL,NULL,'datetime_ymd',NULL,NULL,'soft_typed',NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,'@CALCDATE([first_monday], 15+[time_diff], \'h\')',NULL,0),(271,'first_monday_1700',NULL,'admin',NULL,250,NULL,NULL,'text','First Monday at 17:00 with timezone offset of [time_diff]\n@CALCDATE([first_monday], 17+[time_diff], \'h\')\n\nValidation should be YMD H:M',NULL,NULL,'datetime_ymd',NULL,NULL,'soft_typed',NULL,0,NULL,0,NULL,NULL,NULL,NULL,0,'@CALCDATE([first_monday], 17+[time_diff], \'h\')',NULL,0),(271,'first_name',NULL,'contact_info','Contact Info',53,NULL,'<div class=\"rich-text-field-label\"><ul> <li style=\"font-size: 12pt;\"><span style=\"font-size: 12pt; font-weight: normal;\">We need to collect some </span><span style=\"font-size: 12pt;\">basic information </span><span style=\"font-size: 12pt; font-weight: normal;\">from you to ensure we are able to reach you and </span><span style=\"font-size: 12pt;\">send payments</span><span style=\"font-size: 12pt; font-weight: normal;\">. </span></li> <li style=\"font-size: 12pt;\"><span style=\"font-size: 12pt; font-weight: normal;\">We will store this information </span><span style=\"font-size: 12pt;\">securely </span><span style=\"font-size: 12pt; font-weight: normal;\">and separately from any other research data.</span></li> <li style=\"font-size: 12pt;\"><span style=\"font-size: 12pt; font-weight: normal;\">Make sure you enter your email correctly!</span></li> </ul></div>','text','What is your first name?',NULL,NULL,NULL,NULL,NULL,'soft_typed',NULL,1,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'g',NULL,'postsession',NULL,147,NULL,NULL,'radio','Act as a partner in your behavior change','1, not at all\\n2, a little\\n3, sometimes\\n4, a great deal\\n5, always',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,0,NULL,NULL,NULL,'ces',0,NULL,NULL,0),(271,'gg_1',NULL,'sunday',NULL,207,NULL,NULL,'descriptive','Great decision! Setting a drinking limit is a powerful way to stay in control. Alternating alcoholic drinks with water can make it easier to stick to your plan and feel better the next day.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_10',NULL,'sunday',NULL,216,NULL,NULL,'descriptive','Setting a limit is a sign that you care about your health and well-being. Mixing in non-alcoholic drinks can help you stay on track and stay hydrated.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_11',NULL,'sunday',NULL,217,NULL,NULL,'descriptive','Great job committing to a goal. Removing easy opportunities to drink more than planned—such as carrying only enough money for your intended drinks—can support your success.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_12',NULL,'sunday',NULL,218,NULL,NULL,'descriptive','Well done. Deciding ahead of time how you’ll respond if offered another drink can make it easier to stay confident and stick with the choice you already made.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_2',NULL,'sunday',NULL,208,NULL,NULL,'descriptive','Nice work setting a goal. People are often more successful when they decide in advance how many drinks they\'ll have rather than making decisions in the moment.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_3',NULL,'sunday',NULL,209,NULL,NULL,'descriptive','You’ve already taken an important step by choosing a limit. Slowing down and taking time between drinks can help your choices stay aligned with your goal.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_4',NULL,'sunday',NULL,210,NULL,NULL,'descriptive','Excellent choice. Staying in control of your own drink purchases can make it easier to track your drinking and stick with the limit you set.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_5',NULL,'sunday',NULL,211,NULL,NULL,'descriptive','Way to go! Eating before or while drinking can help reduce the effects of alcohol and make it easier to pace yourself throughout the evening.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_6',NULL,'sunday',NULL,212,NULL,NULL,'descriptive','Setting a goal shows commitment to yourself. Keeping a simple count of your drinks on your phone can help you stay aware of your progress.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_7',NULL,'sunday',NULL,213,NULL,NULL,'descriptive','Great plan. A quick check-in with yourself during the evening can help you decide whether your drinking is still matching the goal you set.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_8',NULL,'sunday',NULL,214,NULL,NULL,'descriptive','Nice work taking this step. Choosing beverages with lower alcohol content can help you enjoy social situations while staying within your limit.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gg_9',NULL,'sunday',NULL,215,NULL,NULL,'descriptive','You’ve made a thoughtful decision. Spending time with people who respect your goals can make it easier to follow through on them.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=1) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'goodcand',NULL,'pre_screen',NULL,8,NULL,'Approach provider\n','yesno','Do you think the patient in room X would be a good participant for our research study? (They need to be medically stable and speak English)',NULL,NULL,NULL,NULL,NULL,NULL,'[sc_age] >= 18 and [sc_age] <= 65 and [english] = \'1\'',1,NULL,0,'LH',NULL,NULL,NULL,0,NULL,NULL,0),(271,'gp_1',NULL,'sunday',NULL,195,NULL,NULL,'descriptive','Change often begins with paying attention rather than making a commitment. Taking time to reflect on your drinking can still be valuable.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=0) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gp_10',NULL,'sunday',NULL,204,NULL,NULL,'descriptive','Many people find that their motivation for change develops gradually over time rather than all at once.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=0) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gp_11',NULL,'sunday',NULL,205,NULL,NULL,'descriptive','Whether or not you decide to make changes in the future, paying attention to the connection between your drinking and your personal goals can be informative.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=0) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gp_12',NULL,'sunday',NULL,206,NULL,NULL,'descriptive','Taking time to consider both the benefits and costs of drinking can help clarify what matters most to you',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=0) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(271,'gp_2',NULL,'sunday',NULL,196,NULL,NULL,'descriptive','Not everyone is ready to make a change immediately. Many people spend time weighing what they enjoy about drinking against what concerns them.',NULL,NULL,NULL,NULL,NULL,NULL,'([gset]=0) AND\n[event-name]=\"week_1_sms_arm_1\"',0,NULL,0,NULL,NULL,NULL,NULL,0,NULL,NULL,0),(